package com.wtm.firstparty;
import java.util.prefs.Preferences;
public final class NetworkMapDisplaySettings{
 private static final Preferences P=Preferences.userRoot().node("com/wtm/northstar/network-map-display");
 public static boolean mainDealers(){return P.getBoolean("main.dealers",false);}public static void mainDealers(boolean v){P.putBoolean("main.dealers",v);}public static boolean mainCenters(){return P.getBoolean("main.centers",true);}public static void mainCenters(boolean v){P.putBoolean("main.centers",v);}public static boolean mainOther(){return P.getBoolean("main.other",false);}public static void mainOther(boolean v){P.putBoolean("main.other",v);}public static boolean mainRegions(){return P.getBoolean("main.regions",false);}public static void mainRegions(boolean v){P.putBoolean("main.regions",v);}
 public static boolean playbackDealers(){return P.getBoolean("playback.dealers",false);}public static void playbackDealers(boolean v){P.putBoolean("playback.dealers",v);}public static boolean playbackCenters(){return P.getBoolean("playback.centers",true);}public static void playbackCenters(boolean v){P.putBoolean("playback.centers",v);}public static boolean playbackOther(){return P.getBoolean("playback.other",false);}public static void playbackOther(boolean v){P.putBoolean("playback.other",v);}public static boolean playbackRegions(){return P.getBoolean("playback.regions",false);}public static void playbackRegions(boolean v){P.putBoolean("playback.regions",v);}
 public static boolean show(String category,boolean playback){String c=category==null?"":category.toLowerCase();if(c.contains("dealer"))return playback?playbackDealers():mainDealers();if(c.contains("logistics center"))return playback?playbackCenters():mainCenters();return playback?playbackOther():mainOther();}private NetworkMapDisplaySettings(){}
}
